-- Dados idempotentes de demonstracao carregados pelo Flyway.

UPDATE usuarios
SET nome = CASE id
    WHEN '20000000-0000-0000-0000-000000000001' THEN 'Socrates de Souza'
    WHEN '20000000-0000-0000-0000-000000000002' THEN 'Platao Almeida'
    WHEN '20000000-0000-0000-0000-000000000003' THEN 'Aristoteles Oliveira'
    ELSE nome END
WHERE id IN ('20000000-0000-0000-0000-000000000001', '20000000-0000-0000-0000-000000000002',
             '20000000-0000-0000-0000-000000000003');

